  public void onSurfaceCreated(GL10 g,EGLConfig e){GLES20.glClearColor(0,0,0,0);GLES20.glEnable(GLES20.GL_DEPTH_TEST);GLES20.glEnable(GLES20.GL_CULL_FACE);GLES20.glEnable(GLES20.GL_BLEND);GLES20.glBlendFunc(GLES20.GL_SRC_ALPHA,GLES20.GL_ONE_MINUS_SRC_ALPHA);pg=prog(VS,FS);ap=GLES20.glGetAttribLocation(pg,"aPos");an=GLES20.glGetAttribLocation(pg,"aNormal");apart=GLES20.glGetAttribLocation(pg,"aPart");umvp=GLES20.glGetUniformLocation(pg,"uMvp");umodel=GLES20.glGetUniformLocation(pg,"uModel");uc=GLES20.glGetUniformLocation(pg,"uColor");ul=GLES20.glGetUniformLocation(pg,"uLightDir");ut=GLES20.glGetUniformLocation(pg,"uThrottle");usp=GLES20.glGetUniformLocation(pg,"uSurfPitch");usr=GLES20.glGetUniformLocation(pg,"uSurfRoll");usy=GLES20.glGetUniformLocation(pg,"uSurfYaw");ug=GLES20.glGetUniformLocation(pg,"uGear");um=GLES20.glGetUniformLocation(pg,"uMainComp");un=GLES20.glGetUniformLocation(pg,"uNoseComp");ProceduralFighterMesh.Mesh m=ProceduralFighterMesh.build();vb=ByteBuffer.allocateDirect(m.data.length*4).order(ByteOrder.nativeOrder()).asFloatBuffer();vb.put(m.data).position(0);count=m.vertexCount();last=System.nanoTime();}
