  static final String VS="uniform mat4 uMvp;uniform mat4 uModel;uniform float uSurfPitch,uSurfRoll,uSurfYaw,uThrottle,uGear,uMainComp,uNoseComp;attribute vec3 aPos,aNormal;attribute float aPart;varying vec3 vN;varying float vPart,vThr,vGear,vZ,vX,vRetract;mat2 rr(float a){float c=cos(a),s=sin(a);return mat2(c,-s,s,c);}void main(){vec3 p=aPos,n=aNormal;float d=.0174532925;vRetract=0.;if(aPart>3.5&&aPart<5.5){float s=aPart<4.5?-1.:1.,a=(-uSurfPitch*18.+s*uSurfRoll*10.)*d;p.yz=rr(a)*(p.yz-vec2(.18,2.15))+vec2(.18,2.15);}else if(aPart>8.5&&aPart<10.5){float s=aPart<9.5?-1.:1.,a=(-uSurfPitch*8.+s*uSurfRoll*20.)*d;p.yz=rr(a)*(p.yz-vec2(.16,.88))+vec2(.16,.88);}else if(aPart>7.5&&aPart<8.5){p.z=3.84+(p.z-3.84)*(.05+1.2*uThrottle);}else if(aPart>12.5&&aPart<14.5){float nose=step(p.z,-2.0),r=1.-uGear,fold=smoothstep(.02,.88,r),seat=smoothstep(.62,.96,r),comp=mix(uMainComp,uNoseComp,nose);vRetract=r;p.y+=comp*.20*uGear;if(nose>.5){float qz=p.z+3.72,qy=p.y+1.66;p.x=mix(p.x,p.x*.35,fold);p.z=mix(p.z,-3.58+qz*.18,fold);p.y=mix(p.y,-.74+qy*.055,fold);}else{float side=p.x<0.?-1.:1.,ax=abs(p.x);p.x=side*mix(ax,.69+(ax-1.70)*.10,fold);p.z=mix(p.z,.83+(p.z-.84)*.12,fold);p.y=mix(p.y,-.76+(p.y+1.72)*.05,fold);}p.y=min(p.y,-.60+.18*uGear);p.y-=.06*seat;}else if(aPart>14.5&&aPart<15.5){float r=1.-uGear,opening=smoothstep(.02,.24,r)*(1.-smoothstep(.68,.96,r)),side=p.x<0.?-1.:1.;p.x+=side*.27*opening;p.y-=.10*opening;p.y=min(p.y,-.50);vRetract=r;}vN=normalize(mat3(uModel)*n);vPart=aPart;vThr=uThrottle;vGear=uGear;vZ=p.z;vX=p.x;gl_Position=uMvp*vec4(p,1.);}";
  static final String FS="precision mediump float;uniform vec4 uColor;uniform vec3 uLightDir;varying vec3 vN;varying float vPart,vThr,vGear,vZ,vX,vRetract;void main(){vec3 n=normalize(vN),c=uColor.rgb;float li=.22+.72*max(dot(n,normalize(uLightDir)),0.);float a=1.;if(vPart>.5&&vPart<1.5){c=vec3(.02,.06,.08);a=.96;}else if(vPart>7.5&&vPart<8.5){c=mix(vec3(.1,.3,1.),vec3(1.,.24,.02),vThr);li=.5+1.5*vThr;a=smoothstep(.08,.4,vThr)*.82;}else if(vPart>12.5&&vPart<13.5)c=vec3(.32,.34,.36);else if(vPart>13.5&&vPart<14.5)c=vec3(.025);else if(vPart>14.5&&vPart<15.5)c=vec3(.24,.27,.29);else if(vPart>18.5&&vPart<20.5)c=vec3(.02,.025,.028);else if(vPart>20.5&&vPart<22.5){c=vec3(.32,.18,.08);li=.5+vThr;}if(vPart>12.5&&vPart<14.5)a*=1.-smoothstep(.72,.90,vRetract);gl_FragColor=vec4(c*li,a);}";
